package dev.cosmerearcanists.power;
import com.mojang.authlib.GameProfile;
import dev.cosmerearcanists.*;
import dev.cosmerearcanists.compounding.PowerSources;
import dev.cosmerearcanists.equipment.*;
import dev.cosmerearcanists.hemalurgy.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.gametest.framework.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.damagesource.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.*;
import net.minecraft.world.entity.monster.Zombie;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.common.util.FakePlayer;
import net.neoforged.neoforge.event.entity.living.LivingDeathEvent;
import net.neoforged.neoforge.event.entity.player.PlayerEvent;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder(CosmereArcanists.MOD_ID)
@PrefixGameTestTemplate(false)
public final class HemalurgyGameTests {
    private static FakePlayer player(GameTestHelper h){var p=new FakePlayer(h.getLevel(),new GameProfile(UUID.randomUUID(),"SpikeTest"));p.setGameMode(GameType.SURVIVAL);p.setPos(net.minecraft.world.phys.Vec3.atCenterOf(h.absolutePos(new BlockPos(1,8,1))));PowerAttributes.migrate(p);return p;}
    private static ItemStack equip(FakePlayer p,String metal,int count){var stack=new ItemStack(EquipmentContent.SPIKES.get(metal).get(),count);p.setItemInHand(InteractionHand.MAIN_HAND,stack);return stack;}
    private static LivingDeathEvent pending(FakePlayer attacker,FakePlayer victim){victim.setHealth(0);var event=new LivingDeathEvent(victim,attacker.damageSources().playerAttack(attacker));HemalurgyService.capture(event);return event;}
    @GameTest(template="empty") public static void actualMeleeKillingHitChargesSpikeFromAPoweredMob(GameTestHelper h){var p=player(h);var weapon=equip(p,"steel",1);var victim=new Zombie(EntityType.ZOMBIE,h.getLevel()){
        final AttributeInstance power=new AttributeInstance(PowerAttributes.holder("a:steel"),a->{});
        @Override public AttributeInstance getAttribute(Holder<Attribute> attribute){return power!=null&&attribute==PowerAttributes.holder("a:steel")?power:super.getAttribute(attribute);}
    };try{victim.setPos(p.position().add(1,0,0));h.getLevel().addFreshEntity(victim);victim.getAttribute(PowerAttributes.holder("a:steel")).setBaseValue(1);p.attack(victim);HemalurgyService.flush();h.assertTrue(victim.isAlive()&&!HemalurgicSpikes.marked(weapon),"A nonfatal actual attack cannot steal power");victim.setHealth(.01f);p.attack(victim);if(victim.isAlive()){victim.invulnerableTime=0;p.attack(victim);}HemalurgyService.flush();var charge=HemalurgicSpikes.contents(weapon);h.assertTrue(!victim.isAlive()&&charge!=null&&charge.power().equals("a:steel"),"Actual player melee/death events charge a spike from a mob with that registered power");h.assertTrue(victim.getAttribute(PowerAttributes.holder("a:steel")).getBaseValue()==0&&charge.sources().getFirst().identity().equals(victim.getUUID()),"The mob loses its personal source and the spike preserves its Identity");}finally{victim.discard();HemalurgyService.flush();}h.succeed();}
    @GameTest(template="empty") public static void playerLosesStrongestMatchingPowerAndSpikePersistsWithoutGrantingIt(GameTestHelper h){var p=player(h);var donor=player(h);var weapon=equip(p,"steel",1);PowerAttributes.set(donor,"a:steel",1.5);PowerAttributes.set(donor,"a:iron",1);PowerAttributes.set(donor,"f:steel",2);PowerData.reserve(donor,"steel",40);pending(p,donor);h.assertTrue(!HemalurgicSpikes.marked(weapon),"Theft waits until death cancellation is final");HemalurgyService.flush();var charge=HemalurgicSpikes.contents(weapon);h.assertTrue(charge!=null&&charge.power().equals("a:steel")&&Math.abs(charge.strength()-1.5*HemalurgyConfig.RETENTION.get())<1e-9,"The strongest eligible personal power is stored at configured retention");h.assertTrue(PowerAttributes.baseStrength(donor,"a:steel")==0&&PowerAttributes.baseStrength(donor,"a:iron")==1&&PowerAttributes.baseStrength(donor,"f:steel")==2&&PowerData.reserve(donor,"steel")==40,"Only the selected matching power is removed, not other powers or metal reserves");h.assertTrue(PowerAttributes.baseStrength(p,"a:steel")==0&&weapon.getMaxStackSize()==1,"Carrying a charged spike grants no power and the item cannot stack");var saved=weapon.save(h.getLevel().registryAccess());var loaded=ItemStack.parseOptional(h.getLevel().registryAccess(),(net.minecraft.nbt.CompoundTag)saved);h.assertTrue(HemalurgicSpikes.contents(loaded).equals(charge),"Spike ID, donor, power strength and source Identity survive item serialization");h.succeed();}
    @GameTest(template="empty") public static void projectileWrongMetalOffhandAndOrdinaryMobKillsDoNotCharge(GameTestHelper h){var p=player(h);var donor=player(h);PowerAttributes.set(donor,"a:steel",1);var weapon=equip(p,"steel",1);donor.setHealth(0);var arrowType=h.getLevel().registryAccess().registryOrThrow(Registries.DAMAGE_TYPE).getHolderOrThrow(DamageTypes.ARROW);HemalurgyService.capture(new LivingDeathEvent(donor,new DamageSource(arrowType,p,p)));HemalurgyService.flush();h.assertTrue(!HemalurgicSpikes.marked(weapon)&&PowerAttributes.baseStrength(donor,"a:steel")==1,"A projectile damage type cannot charge a held spike");p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);p.setItemInHand(InteractionHand.OFF_HAND,weapon);pending(p,donor);HemalurgyService.flush();h.assertTrue(!HemalurgicSpikes.marked(weapon),"Merely holding a spike in the offhand cannot steal");p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);var wrong=equip(p,"bronze",1);pending(p,donor);HemalurgyService.flush();h.assertTrue(!HemalurgicSpikes.marked(wrong)&&PowerAttributes.baseStrength(donor,"a:steel")==1,"The wrong metal cannot steal an incompatible power");var zombie=new Zombie(EntityType.ZOMBIE,h.getLevel());zombie.setHealth(0);var right=equip(p,"steel",1);HemalurgyService.capture(new LivingDeathEvent(zombie,p.damageSources().playerAttack(p)));HemalurgyService.flush();h.assertTrue(!HemalurgicSpikes.marked(right),"Ordinary mobs do not provide fabricated Allomancy");h.succeed();}
    @GameTest(template="empty") public static void canceledDeathsConfigDisableAndChangedWeaponPreserveTheDonor(GameTestHelper h){var p=player(h);var donor=player(h);var weapon=equip(p,"steel",1);PowerAttributes.set(donor,"a:steel",1);var event=pending(p,donor);event.setCanceled(true);HemalurgyService.flush();h.assertTrue(!HemalurgicSpikes.marked(weapon)&&PowerAttributes.baseStrength(donor,"a:steel")==1,"Cancellation even after capture cannot steal power");boolean enabled=HemalurgyConfig.ENABLED.get();try{pending(p,donor);HemalurgyConfig.ENABLED.set(false);HemalurgyService.flush();h.assertTrue(!HemalurgicSpikes.marked(weapon)&&PowerAttributes.baseStrength(donor,"a:steel")==1,"A disabled feature preserves queued donor/item contents");}finally{HemalurgyConfig.ENABLED.set(enabled);}pending(p,donor);p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);HemalurgyService.flush();h.assertTrue(!HemalurgicSpikes.marked(weapon)&&PowerAttributes.baseStrength(donor,"a:steel")==1,"Changing the weapon before settlement cannot lose the donor's power");h.succeed();}
    @GameTest(template="empty") public static void oneSpikeSplitsFromStackAndPreservesMixedIdentitySources(GameTestHelper h){var p=player(h);var donor=player(h);equip(p,"steel",4);PowerAttributes.set(donor,"a:steel",1);PowerSources.grant(donor,"a:steel",.5,null);pending(p,donor);pending(p,donor);HemalurgyService.flush();var charged=p.getMainHandItem();var charge=HemalurgicSpikes.contents(charged);int loose=p.getInventory().items.stream().filter(s->s.getItem() instanceof SpikeItem&&!HemalurgicSpikes.marked(s)).mapToInt(ItemStack::getCount).sum();h.assertTrue(charge!=null&&charged.getCount()==1&&loose==3,"Exactly one spike is charged and all three remaining spikes survive");h.assertTrue(charge.sources().size()==2&&charge.sources().stream().anyMatch(v->v.identity()==null)&&charge.sources().stream().anyMatch(v->donor.getUUID().equals(v.identity())),"Neutral and keyed source portions are kept separate");var another=player(h);PowerAttributes.set(another,"a:steel",5);pending(p,another);HemalurgyService.flush();h.assertTrue(HemalurgicSpikes.contents(charged).equals(charge)&&PowerAttributes.baseStrength(another,"a:steel")==5,"An already charged spike cannot overwrite contents or take another power");h.succeed();}
    @GameTest(template="empty") public static void temporaryAndEquipmentModifiersCannotBeStolenAsPersonalPower(GameTestHelper h){var p=player(h);var donor=player(h);var weapon=equip(p,"steel",1);PowerAttributes.instance(donor,"a:steel").addTransientModifier(new AttributeModifier(ResourceLocation.fromNamespaceAndPath(CosmereArcanists.MOD_ID,"theft_test_external"),5,AttributeModifier.Operation.ADD_VALUE));pending(p,donor);HemalurgyService.flush();h.assertTrue(!HemalurgicSpikes.marked(weapon)&&PowerAttributes.baseStrength(donor,"a:steel")==0&&PowerAttributes.strength(donor,"a:steel")==5,"Only personal bases can be extracted; temporary or spike/equipment contributions cannot be copied");h.succeed();}
    @GameTest(template="empty") public static void pendingPlayerTheftSettlesBeforeRespawnDataIsCloned(GameTestHelper h){var p=player(h);var donor=player(h);var next=player(h);var weapon=equip(p,"steel",1);PowerAttributes.set(donor,"a:steel",1);pending(p,donor);NeoForge.EVENT_BUS.post(new PlayerEvent.Clone(next,donor,true));h.assertTrue(HemalurgicSpikes.contents(weapon)!=null&&PowerAttributes.baseStrength(next,"a:steel")==0,"The original loses power before the normal clone handler copies attributes");PowerAttributes.migrate(next);h.assertTrue(PowerAttributes.baseStrength(next,"a:steel")==0,"Legacy origin migration cannot regrant the stolen power");HemalurgyService.flush();h.succeed();}
    @GameTest(template="empty") public static void chargedSpikesCannotBeCraftedFiredOrOverwritten(GameTestHelper h){var p=player(h);var donor=player(h);var weapon=equip(p,"steel",1);PowerAttributes.set(donor,"a:steel",1);pending(p,donor);HemalurgyService.flush();h.assertTrue(dev.cosmerearcanists.filing.Filings.protectedMaterial(weapon)&&!EquipmentContent.CROSSBOW.get().getAllSupportedProjectiles().test(weapon),"Charged contents are protected from crafting and crossbow multishot duplication");var charge=HemalurgicSpikes.contents(weapon);h.assertTrue(!HemalurgicSpikes.store(weapon,charge)&&weapon.hasFoil(),"Charging cannot overwrite existing contents; charged item has a visible glint");h.succeed();}
}
